import { useState, useCallback, memo, useEffect, useRef } from 'react';
import '../styles/searchForm.css';

const GEONAMES_USERNAME = 'bobby0618'; // Замените на ваш username от GeoNames

const SearchForm = memo(({ 
  onSearch, 
  initialValues,
  wide, 
  isLoading
}) => {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [date, setDate] = useState('');
  const [showFromSuggestions, setShowFromSuggestions] = useState(false);
  const [showToSuggestions, setShowToSuggestions] = useState(false);
  const [allCities, setAllCities] = useState([]);
  const [filteredFromCities, setFilteredFromCities] = useState([]);
  const [filteredToCities, setFilteredToCities] = useState([]);
  const [isFetchingCities, setIsFetchingCities] = useState(false);
  const [error, setError] = useState(null);
  const fromInputRef = useRef(null);
  const toInputRef = useRef(null);
  const hasFetchedCities = useRef(false);

  useEffect(() => {
    setFrom(initialValues.from || '');
    setTo(initialValues.to || '');
    setDate(initialValues.date || '');
  }, [initialValues]);

  const handleSubmit = useCallback((e) => {
    e.preventDefault();
    if (!isLoading && from && to) {
      onSearch({ from, to, date });
    }
  }, [from, to, date, onSearch, isLoading]);

  // Загрузка всех городов России при первом вводе
  const fetchRussianCities = useCallback(async () => {
    try {
      setIsFetchingCities(true);
      setError(null);
      
      const response = await fetch(
        `http://api.geonames.org/searchJSON?featureClass=P&country=RU&maxRows=1000&username=${GEONAMES_USERNAME}`
      );
      
      if (!response.ok) {
        throw new Error(`Ошибка HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (!data.geonames) {
        throw new Error('Неверный формат данных от API');
      }
      
      const cities = data.geonames.map(city => ({
        name: city.name,
        region: city.adminName1
      }));
      
      setAllCities(cities);
      hasFetchedCities.current = true;
      return cities;
    } catch (err) {
      console.error('Ошибка при загрузке городов:', err);
      setError('Не удалось загрузить список городов. Попробуйте позже.');
      return [];
    } finally {
      setIsFetchingCities(false);
    }
  }, []);

  // Фильтрация городов по первым буквам (локально)
  const filterCities = useCallback((input, cities) => {
    if (!input) return [];
    return cities.filter(city => 
      city.name.toLowerCase().startsWith(input.toLowerCase())
    ).slice(0, 20); // Ограничиваем количество результатов
  }, []);

  const handleFromChange = useCallback(async (e) => {
    const value = e.target.value;
    setFrom(value);
    
    if (!hasFetchedCities.current && value.length > 0) {
      const cities = await fetchRussianCities();
      setFilteredFromCities(filterCities(value, cities));
    } else {
      setFilteredFromCities(filterCities(value, allCities));
    }
  }, [allCities, fetchRussianCities, filterCities]);

  const handleToChange = useCallback(async (e) => {
    const value = e.target.value;
    setTo(value);
    
    if (!hasFetchedCities.current && value.length > 0) {
      const cities = await fetchRussianCities();
      setFilteredToCities(filterCities(value, cities));
    } else {
      setFilteredToCities(filterCities(value, allCities));
    }
  }, [allCities, fetchRussianCities, filterCities]);

  const handleDateChange = useCallback((e) => {
    setDate(e.target.value);
  }, []);

  const selectCity = useCallback((setCity, setShowSuggestions, cityName) => {
    setCity(cityName);
    setShowSuggestions(false);
  }, []);

  // Закрытие списка при клике вне инпута
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (fromInputRef.current && !fromInputRef.current.contains(e.target)) {
        setShowFromSuggestions(false);
      }
      if (toInputRef.current && !toInputRef.current.contains(e.target)) {
        setShowToSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="search-form-container">
      <form onSubmit={handleSubmit} className={`search-form ${wide ? 'wide' : ''}`}>
        {wide && <h2 className="form-title">Поиск билетов</h2>}
        
        {error && (
          <div className="error-message">
            {error}
            <button onClick={() => setError(null)}>×</button>
          </div>
        )}
        
        <div className="form-grid">
          <div className="input-group">
            <label htmlFor="from">Откуда</label>
            <div className="input-wrapper" ref={fromInputRef}>
              <input
                id="from"
                name="from"
                value={from}
                onChange={handleFromChange}
                onFocus={() => {
                  setShowFromSuggestions(true);
                  if (from) setFilteredFromCities(filterCities(from, allCities));
                }}
                placeholder="Город отправления"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showFromSuggestions && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка городов...</li>
                  ) : filteredFromCities.length > 0 ? (
                    filteredFromCities.map(city => (
                      <li 
                        key={`${city.name}-${city.region}`} 
                        onClick={() => selectCity(setFrom, setShowFromSuggestions, city.name)}
                      >
                        {city.name} {city.region && `(${city.region})`}
                      </li>
                    ))
                  ) : (
                    <li className="no-results">
                      {from ? 'Ничего не найдено' : 'Начните вводить название города'}
                    </li>
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group">
            <label htmlFor="to">Куда</label>
            <div className="input-wrapper" ref={toInputRef}>
              <input
                id="to"
                name="to"
                value={to}
                onChange={handleToChange}
                onFocus={() => {
                  setShowToSuggestions(true);
                  if (to) setFilteredToCities(filterCities(to, allCities));
                }}
                placeholder="Город прибытия"
                autoComplete="off"
                disabled={isFetchingCities}
              />
              {showToSuggestions && (
                <ul className="suggestions">
                  {isFetchingCities ? (
                    <li className="loading">Загрузка городов...</li>
                  ) : filteredToCities.length > 0 ? (
                    filteredToCities.map(city => (
                      <li 
                        key={`${city.name}-${city.region}`} 
                        onClick={() => selectCity(setTo, setShowToSuggestions, city.name)}
                      >
                        {city.name} {city.region && `(${city.region})`}
                      </li>
                    ))
                  ) : (
                    <li className="no-results">
                      {to ? 'Ничего не найдено' : 'Начните вводить название города'}
                    </li>
                  )}
                </ul>
              )}
            </div>
          </div>

          <div className="input-group date-group">
            <label htmlFor="date">Дата (необязательно)</label>
            <div className="input-wrapper">
              <input
                id="date"
                name="date"
                type="date"
                value={date}
                onChange={handleDateChange}
                min={new Date().toISOString().split('T')[0]}
              />
            </div>
          </div>
        </div>

        <div className="search-button-container">
          <button 
            type="submit" 
            className="search-button"
            disabled={!from || !to || isLoading || isFetchingCities}
          >
            {isLoading ? 'Загрузка...' : 'Найти билеты'}
          </button>
        </div>
      </form>
    </div>
  );
});

export default SearchForm;
